save(416,dict(paragraphs=["Nutan Sarawagi writes in Hindi and English. Her contributor biographies in Different Truths and the Inner Child Press anthology The Heart of a Poet connect her writing with a background in education and professional design. They also describe a sustained concern for women, children and those affected by war. Her attention to the colour and movement of language is evident in the Hindi poem presented here.","Alfazon Se Nikle Do Shabd makes words themselves speak: they laugh, cry, fail to be understood and grow afraid of their own expression. The plea to be allowed to speak gradually becomes a way of examining the self and recognising another person. By the closing movement, ink and new colours make writing an act of renewed understanding, with a story taking shape between speaker and listener."],sources=[source('Different Truths — Life Don’t Go, Nutan Sarawagi','https://www.differenttruths.com/life-dont-go/','Poem byline and contributor biography: education, designer, women/children and children of war.','search_index_full_poem_and_bio; direct open cache miss'),source('Inner Child Press — The Heart of a Poet,2020','https://www.innerchildpress.com/resources/The%20Heart%20of%20a%20Poet%202020%20GRATIS.pdf','Printed page236 contributor biography: English/Hindi writing, education, design and thematic interests.','search_index_pdf_biography; direct open exceeded size limit')],identity_match='Archived author biography matches unusual combination of education degree, designer profession, English/Hindi poetry and concern for women/children of war in two literary sources. Nepal namesake material excluded.',captured_biography_source='kb/artifacts/content-import/editions/issue-34/poem-609.html; complete Author section read. Archive-discovered writer absent from directory profile JSON.',poems_read=[dict(id=609,title='अल्फाजों से निकले दो शब्द',coverage='Complete original Hindi poem and complete archived author biography',basis='Words personified, communication/forgetting, fear of expression, self-examination, renewed story in ink/colour.')],limitations=['Captured Women’s Studies qualification and sculpture interest not externally corroborated, so not repeated in new narrative.','Anthology contribution is not represented as an individually authored collection. No solo book confirmed.','Current city and employment not asserted from older contributor notes.'],search_queries=['"Nutan Sarawagi" poet','"Nutan Sarawagi" Hindi poet','"नूतन सरावगी" कविता'],next_action='Author/editor review and confirmation of qualifications and bibliography.'))
